const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define locations
  const grindavik = ee.Geometry.Point([-22.43, 63.84]);
  const reykjavik = ee.Geometry.Point([-21.95, 64.15]);

  // Define date range (Nov 21, 2024)
  const startDate = '2024-11-21';
  const endDate = '2024-11-22';

  // Load VIIRS Nighttime Lights daily product
  let collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filterDate('2024-11-01', '2024-11-30');

  const collectionSize = await collection.size().getInfo();
  console.log(`Collection size: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No VIIRS data found for November 2024.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get the most recent image
  const image = collection.sort('system:time_start', false).first();
  const avgRad = image.select('avg_rad');

  // Calculate nighttime light intensity for Grindavík
  const grindavikStats = await avgRad.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: grindavik.buffer(2000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const grindavikCount = await avgRad.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: grindavik.buffer(2000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  // Calculate nighttime light intensity for Reykjavík
  const reykjavikStats = await avgRad.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: reykjavik.buffer(2000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const reykjavikCount = await avgRad.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: reykjavik.buffer(2000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const grindavikLight = grindavikStats.avg_rad;
  const reykjavikLight = reykjavikStats.avg_rad;
  const grindavikPixels = grindavikCount.avg_rad;
  const reykjavikPixels = reykjavikCount.avg_rad;

  console.log(`Grindavík: Light=${grindavikLight}, Pixels=${grindavikPixels}`);
  console.log(`Reykjavík: Light=${reykjavikLight}, Pixels=${reykjavikPixels}`);

  // Check for no valid pixels
  if (grindavikPixels === 0 || reykjavikPixels === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for invalid values
  if (grindavikLight === null || grindavikLight === undefined || 
      reykjavikLight === null || reykjavikLight === undefined ||
      isNaN(grindavikLight) || isNaN(reykjavikLight)) {
    console.log('Calculation failed - invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare the values
  console.log(`Comparison: Grindavík (${grindavikLight.toFixed(4)}) vs Reykjavík (${reykjavikLight.toFixed(4)})`);

  if (grindavikLight > reykjavikLight) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
